import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { chromium } from 'playwright-core';

export const DEFAULT_PROFILE_DIR = path.join(os.homedir(), '.local', 'share', 'opscode', 'browser-profile');
export const DEVTOOLS_PORT_FILE = path.join(DEFAULT_PROFILE_DIR, 'DevToolsActivePort');

/**
 * Read DevToolsActivePort generated by Opscode embedded Chrome
 */
export function getOpscodeDevToolsPort(profileDir = DEFAULT_PROFILE_DIR) {
  const portFile = path.join(profileDir, 'DevToolsActivePort');
  if (!fs.existsSync(portFile)) return null;
  try {
    const content = fs.readFileSync(portFile, 'utf8').trim();
    const lines = content.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
    if (!lines.length) return null;
    const port = parseInt(lines[0], 10);
    return Number.isFinite(port) && port > 0 ? port : null;
  } catch {
    return null;
  }
}

/**
 * Check if the CDP HTTP endpoint responds
 */
export async function isCdpEndpointActive(port, timeoutMs = 1500) {
  if (!port) return false;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetch(`http://127.0.0.1:${port}/json/version`, {
      signal: controller.signal,
    });
    clearTimeout(timer);
    return res.ok;
  } catch {
    clearTimeout(timer);
    return false;
  }
}

/**
 * Locate system Chrome / Chromium binary if available
 */
export function findSystemBrowserExecutable() {
  const candidates = [
    '/usr/bin/google-chrome',
    '/usr/bin/google-chrome-stable',
    '/usr/bin/chromium',
    '/usr/bin/chromium-browser',
    '/snap/bin/chromium',
    '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  ];
  for (const c of candidates) {
    if (fs.existsSync(c)) return c;
  }
  return null;
}

/**
 * Acquire a Playwright browser session:
 * 1. Connects to Opscode's internal browser via CDP if active
 * 2. Falls back to launching standalone Chrome/Chromium
 */
export async function getBrowserSession(options = {}) {
  const {
    url,
    headless = process.env.HEADLESS === 'true',
    forceNewPage = false,
  } = options;

  const port = getOpscodeDevToolsPort();
  const cdpActive = port ? await isCdpEndpointActive(port) : false;

  if (cdpActive) {
    try {
      const browser = await chromium.connectOverCDP(`http://127.0.0.1:${port}`);
      const contexts = browser.contexts();
      const context = contexts.length > 0 ? contexts[0] : await browser.newContext();
      let page;
      const pages = context.pages();
      if (!forceNewPage && pages.length > 0) {
        page = pages[pages.length - 1];
      } else {
        page = await context.newPage();
      }

      if (url && page.url() !== url && url !== 'about:blank') {
        try {
          await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 30000 });
        } catch (e) {
          console.warn(`[CDP] Initial navigation warning: ${e.message}`);
        }
      }

      return {
        browser,
        context,
        page,
        mode: 'opscode-cdp',
        port,
        isCdp: true,
      };
    } catch (err) {
      console.warn(`[CDP] Failed to connect to CDP port ${port}: ${err.message}. Falling back to standalone browser.`);
    }
  }

  // Standalone fallback
  const executablePath = findSystemBrowserExecutable();
  const launchOptions = {
    headless,
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage'],
  };
  if (executablePath) {
    launchOptions.executablePath = executablePath;
  }

  const browser = await chromium.launch(launchOptions);
  const context = await browser.newContext({
    viewport: { width: 1280, height: 800 },
  });
  const page = await context.newPage();

  if (url && url !== 'about:blank') {
    try {
      await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 30000 });
    } catch (e) {
      console.warn(`[Standalone] Navigation warning: ${e.message}`);
    }
  }

  return {
    browser,
    context,
    page,
    mode: 'standalone',
    port: null,
    isCdp: false,
  };
}

/**
 * Gracefully release a session
 */
export async function closeSession(session) {
  if (!session) return;
  try {
    if (session.isCdp) {
      // For CDP, disconnect rather than killing Opscode's browser process
      await session.browser.close();
    } else {
      await session.browser.close();
    }
  } catch (err) {
    // Ignore close errors
  }
}
